 const at=record.time.at(-1),state=currentStateAt({...project,probes:[]},record,record.time.length-1),duration=Math.min(settings.step*3000,settings.duration);
 if(at-liveTime>Math.min(settings.duration*.1,settings.step*500,.02*speed))return;
