 streamWorker.onmessage=({data})=>{if(version!==streamVersion)return;streamBusy=false;if(data.error){stop();toast(data.error,true);return;}try{record=appendSimulationRecords(record,data.result,{window:settings.duration});if(running){cursor=liveTime=Math.min(targetLiveTime,record.time.at(-1));acquireMore();}}catch(e){stop();toast(e.message,true);}};
