$('#scopes').addEventListener('pointermove',e=>{if(!scopeDrag)return;const d=scopeDrag,dx=e.clientX-d.x,s=scopes[d.i];if(Math.hypot(dx,e.clientY-d.y)>3)d.moved=true;if(d.xy){if(d.moved&&d.plot){s.xShift=d.xShift-dx/d.plot.PW*(d.plot.xr.max-d.plot.xr.min);s.yShift=d.yShift+(e.clientY-d.y)/d.plot.PH*(d.plot.yr.max-d.plot.yr.min);renderScopes();}return;}if(d.moved){s.start=d.start-dx/d.rect.width*s.span;s.follow=false;renderScopes();}});
$('#scopes').addEventListener('pointerup',e=>{if(!scopeDrag)return;const d=scopeDrag;scopeDrag=null;if(!d.moved){stop();if(d.xy){const p=d.plot;if(!p)return;let best=null,distance=Infinity;for(const point of xySamples(p.series,cursor,true)){if(!point)continue;const px=p.L+(point.x-p.xr.min)/(p.xr.max-p.xr.min)*p.PW,py=p.T+(p.yr.max-point.y)/(p.yr.max-p.yr.min)*p.PH,dist=Math.hypot(px-(e.clientX-d.rect.left),py-(e.clientY-d.rect.top));if(dist<distance){distance=dist;best=point;}}if(best)cursor=best.t;renderScene();renderScopes();updateReadouts();return;}const s=scopes[d.i],fraction=Math.max(0,Math.min(1,(e.clientX-d.rect.left-62)/(d.rect.width-62-15)));cursor=s.start+fraction*s.span;cursor=record.time[sampleIndex()];renderScene();renderScopes();updateReadouts();}});
$('#timeline').oninput=e=>{stop();if(!record)return;cursor=record.time[Number(e.target.value)]||0;scopes.forEach(s=>s.follow=true);renderScene();renderScopes();updateReadouts();};
function toggleScopes(hidden){$('#showScopes').textContent=project.scopes?'Zobrazit osciloskopy':'+ Osciloskop';$('#instruments').hidden=hidden;$('#scopeResize').hidden=hidden;$('#showScopes').hidden=!hidden;setTimeout(applyCamera,0);}$('#scopeToggle').onclick=()=>toggleScopes(true);$('#showScopes').onclick=()=>project.scopes?toggleScopes(false):createScope();
$('#libraryToggle').onclick=()=>{if(innerWidth<650){$('#workbench').classList.remove('library-hidden');$('#workbench').classList.toggle('library-open');}else $('#workbench').classList.toggle('library-hidden');applyCamera();};$('#libraryClose').onclick=()=>{$('#workbench').classList.add('library-hidden');$('#workbench').classList.remove('library-open');applyCamera();};$('#propertiesToggle').onclick=()=>{if(innerWidth<900){$('#workbench').classList.remove('inspector-hidden');$('#workbench').classList.toggle('inspector-open');}else $('#workbench').classList.toggle('inspector-hidden');applyCamera();};$('#inspectorClose').onclick=()=>{$('#workbench').classList.add('inspector-hidden');$('#workbench').classList.remove('inspector-open');applyCamera();};
for(const [id,variable,min,max,axis,sign]of [['leftResize','--left',130,400,'x',1],['rightResize','--right',210,450,'x',-1],['scopeResize','--scope-height',150,innerHeight-240,'y',-1]]){let resize=null;const handle=$('#'+id);handle.addEventListener('pointerdown',e=>{const value=parseFloat(getComputedStyle(document.documentElement).getPropertyValue(variable));resize={start:axis==='x'?e.clientX:e.clientY,value};handle.setPointerCapture(e.pointerId);});handle.addEventListener('pointermove',e=>{if(!resize)return;const at=axis==='x'?e.clientX:e.clientY,v=Math.max(min,Math.min(max,resize.value+(at-resize.start)*sign));document.documentElement.style.setProperty(variable,v+'px');applyCamera();});handle.addEventListener('pointerup',()=>{resize=null;try{localStorage.setItem('shieldio-sim-layout',JSON.stringify({left:getComputedStyle(document.documentElement).getPropertyValue('--left'),right:getComputedStyle(document.documentElement).getPropertyValue('--right'),scope:getComputedStyle(document.documentElement).getPropertyValue('--scope-height')}));}catch{}});handle.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const value=parseFloat(getComputedStyle(document.documentElement).getPropertyValue(variable));document.documentElement.style.setProperty(variable,Math.max(min,Math.min(max,value+(['ArrowRight','ArrowDown'].includes(e.key)?20:-20)*sign))+'px');applyCamera();});}
function filename(ext){return project.title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\w-]+/g,'_').slice(0,70)+'.'+ext;}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function saveProject(){download(filename('shieldio'),JSON.stringify(project,null,2),'application/json');}
$('#save').onclick=saveProject;$('#open').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('Soubor je příliš velký.');load(JSON.parse(await f.text()));}catch(err){toast(err.message,true);}finally{e.target.value='';}};
$('#share').onclick=async()=>{try{const bytes=new TextEncoder().encode(JSON.stringify(project));let stream=new Blob([bytes]).stream(),tag='j',data=bytes;if('CompressionStream'in window){data=new Uint8Array(await new Response(stream.pipeThrough(new CompressionStream('deflate'))).arrayBuffer());tag='z';}let binary='';for(const b of data)binary+=String.fromCharCode(b);const url=location.origin+location.pathname+'#'+tag+btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');if(url.length>50000)throw Error('Pro toto zapojení použijte soubor.');dialog('Sdílet zapojení',`<p>Odkaz obsahuje samostatnou kopii schématu a nastavení měření.</p><input id="shareUrl" readonly value="${esc(url)}"><div class="actions"><button id="copyLink" class="primary">Kopírovat odkaz</button></div>`);$('#copyLink').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Odkaz zkopírován.');}catch{$('#shareUrl').select();}};}catch(e){toast(e.message,true);}};
function exportSvg(){const b=bounds(),charts=$$('.scope-chart svg'),w=Math.max(1000,b.w+80),ch=charts.length?260:0,h=b.h+130+ch;const styles=`text{font-family:ui-monospace,Consolas,monospace;fill:#1b3548}.part-drawing{stroke:#1b3548;stroke-width:2;fill:none}.part-drawing text{stroke:none;fill:#1b3548;font-size:14px}.component-label{font-size:14px}.component-value,.pin-label{font-size:12px}.wire{stroke:#375e75;stroke-width:2.5;fill:none}.junction{fill:#375e75}.wire-hit,.pin,.hit-part,.wire-handle,.flow{display:none}.logic-badge{fill:white;stroke:#1b3548}.logic-text{font-size:15px;text-anchor:middle}.plot-grid{stroke:#d0d9e0;stroke-width:.8}.trace{fill:none;stroke-width:2}.component-label,.component-value{paint-order:stroke;stroke:white;stroke-width:4px}.xy-zero{stroke:#526777;stroke-width:1}.xy-dot{fill:#da8a00;stroke:white;stroke-width:1}`;const diagram=scene.cloneNode(true);diagram.querySelectorAll('.selected').forEach(n=>n.classList.remove('selected'));let plots='';charts.forEach((c,i)=>{let clone=c.cloneNode(true);clone.setAttribute('x',String(35+i*(w-70)/charts.length));clone.setAttribute('y',String(b.h+115));clone.setAttribute('width',String((w-70)/charts.length-12));clone.setAttribute('height','210');const cfg=scopeConfig(i),ms=cfg.mode==='xy'?[project.measurements.find(m=>m.id===cfg.xId),project.measurements.find(m=>m.id===cfg.yId)].filter(Boolean):project.measurements.filter(m=>m.scope===i);plots+=`<text x="${35+i*(w-70)/charts.length}" y="${b.h+105}" font-size="12">${esc(ms.map(measurementName).join(' · '))}</text>`+clone.outerHTML;});return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="--muted:#526777;--grid:#d5dee5;--accent:#006ca2;--selected:#da8a00;--canvas:#fff"><style>${styles}</style><rect width="100%" height="100%" fill="white"/><text x="35" y="34" font-size="21">${esc(project.title)}</text><text x="35" y="57" font-size="11">SHiELDiO Sim · ${esc(names[mode])} · t = ${esc(fmt(record?.time?.[sampleIndex()]||0,'s',7))} · ${new Date().toLocaleDateString('cs-CZ')}</text><g transform="translate(${35-b.x} ${85-b.y})">${diagram.innerHTML}</g>${plots}<text x="35" y="${h-15}" font-size="10">U = rozdíl napětí mezi vývody součástky · proud a → b · výukový model</text></svg>`;}
$('#exportSvg').onclick=()=>download(filename('svg'),exportSvg(),'image/svg+xml');$('#exportPng').onclick=async()=>{try{const url=URL.createObjectURL(new Blob([exportSvg()],{type:'image/svg+xml'}));try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas'),scale=Math.min(2,6000/Math.max(img.width,img.height));canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error('PNG se nepodařilo vytvořit.');download(filename('png'),blob,'image/png');}finally{URL.revokeObjectURL(url);}}catch(e){toast(e.message,true);}};
$('#exportCsv').onclick=()=>{if(!record)return toast('Nejprve spusťte záznam.');if(project.demo?.kind==='diode-iv')return download(filename('csv'),diodeLabCSV(project,record),'text/csv;charset=utf-8');const ms=project.measurements,rows=[['t_s',...ms.map(m=>measurementName(m)+'_'+measurementUnit(m))].join(';')];for(let i=0;i<record.time.length;i++)rows.push([record.time[i],...ms.map(m=>sampleMeasurement(project,m,record,i))].join(';'));download(filename('csv'),rows.join('\n'),'text/csv;charset=utf-8');};
$('#frequencyAnalysis').onclick=async()=>{const ms=project.measurements.filter(m=>m.kind==='voltage');if(!ms.length)return toast('Nejprve přidejte měření napětí na součástce.');stop();dialog('Frekvenční přenos a fáze',`<p>Napětí součástek vůči amplitudě prvního střídavého napěťového zdroje.</p><div class="actions"><label>Od [Hz] <input id="acStart" value="${project.settings.acStart||10}"></label><label>Do [Hz] <input id="acStop" value="${project.settings.acStop||1e6}"></label><button id="acRun" class="primary">Změřit</button></div><div id="acResults"></div>`);$('#acRun').onclick=async()=>{try{const start=number($('#acStart').value),stop=number($('#acStop').value);const probes=ms.flatMap((m,i)=>{const [a,b]=measurementPins(project,m);return [{id:'a'+i,label:measurementName(m),...a},...(b?[{id:'b'+i,label:'reference',...b}]:[])];});const result=await solve({mode:'ac',project:{...copy(project),probes},options:{start,stop,points:240}});busy=false;$('#run').textContent='Spustit';project.settings.acStart=start;project.settings.acStop=stop;saveLocal();let output='';for(let i=0;i<ms.length;i++){const a=result.traces.find(t=>t.id==='a'+i),b=result.traces.find(t=>t.id==='b'+i),vals=a.real.map((v,j)=>({gain:20*Math.log10(Math.max(1e-15,Math.hypot(v-(b?.real[j]||0),a.imag[j]-(b?.imag[j]||0)))),phase:Math.atan2(a.imag[j]-(b?.imag[j]||0),v-(b?.real[j]||0))*180/Math.PI}));const low=Math.min(-40,...vals.map(v=>v.gain)),hi=Math.max(5,...vals.map(v=>v.gain)),x=j=>50+j/(vals.length-1)*500,y=v=>20+(hi-v)/(hi-low)*130,dp=vals.map((v,j)=>(j?'L':'M')+x(j)+' '+y(v.gain)).join(''),phase=vals.map((v,j)=>(j?'L':'M')+x(j)+' '+(20+(180-v.phase)/360*130)).join('');output+=`<p>${esc(measurementName(ms[i]))} · plná čára dB, přerušovaná fáze ±180°</p><svg viewBox="0 0 600 180" style="width:100%;background:var(--canvas)"><path fill="none" stroke="${ms[i].color}" stroke-width="2" d="${dp}"/><path fill="none" stroke="${ms[i].color}" stroke-dasharray="5 4" d="${phase}"/><text x="10" y="20" fill="var(--muted)">${hi.toFixed(1)} dB</text><text x="10" y="150" fill="var(--muted)">${low.toFixed(1)} dB</text><text x="50" y="175" fill="var(--muted)">${fmt(start,'Hz')}</text><text x="500" y="175" fill="var(--muted)">${fmt(stop,'Hz')}</text></svg>`;}$('#acResults').innerHTML=output;}catch(e){$('#solverError').hidden=false;$('#solverError span').textContent=e.message;$('#run').textContent='Spustit';toast(e.message,true);}};};
$('#help').onclick=()=>dialog('Ovládání laboratoře','<p><b>Vybrat:</b> klikněte na součástku nebo vodič. Součástka se zvýrazní přímo svou značkou, vodič výraznou barvou a koncovými body. Tažením čáry posunete úsek, tažením koncového bodu vodič přepojíte.</p><p><b>Propojit:</b> klikněte na dva vývody. Mezilehlými kliknutími vytvoříte ohyby. Esc ukončí spojování. Pravé tlačítko otevře nabídku; u rozkresleného vodiče jej ukončí.</p><p><b>Vstupy:</b> Kliknutí přepne 0/1, tažení vstup přesune. Totéž lze nastavit tlačítky OFF/ON ve vlastnostech. Výstupy ukazují vypočtený stav. Nelze je libovolně vnutit připojenému hradlu.</p><p><b>Měření:</b> vyberte součástku, napětí nebo proud a cílový osciloskop. Napětí je rozdíl mezi jejími vývody, ne jedna náhodná sonda vůči zemi. Kladný proud teče a → b. Pro OZ se měří OUT vůči zemi a proud jeho výstupu.</p><p><b>Čas:</b> simulace průběžně navazuje a čas se nevrací na začátek. Časová základna mění šířku okna. Pauza zachová čas. Šipky procházejí vzorky, dolní posuvník vybírá čas. Kolečko nad osciloskopem mění časové měřítko; tažením grafu posunete okno. Y+/Y− mění svislé měřítko. Reset obnoví počáteční stav.</p><p><b>X–Y:</b> tlačítkem Y–t / X–Y v záhlaví osciloskopu přepnete režim. Vyberte libovolné měřené veličiny pro X a Y. Pro VA charakteristiku dejte na X napětí diody a na Y její proud. Paměť drží stopu, kolečko přibližuje obě osy a kliknutí na stopu vybere vzorek.</p><p><b>Panely:</b> oddělovače vlevo, vpravo a nad osciloskopy lze táhnout. Klávesy: Q výběr, W propojení, R rezistor, C kondenzátor, L cívka, D dioda, V DC zdroj, A AC zdroj, I proudový zdroj, G zem, O OZ, S spínač, Shift+R otočit, Esc zrušit, Delete smazat, mezerník běh/pauza. Bloky FBD a číslicové techniky se neotáčejí.</p><p><b>Modely:</b> výukové modely RLC, diod a OZ s omezením pásma a přeběhu. Výpočet a krok se volí automaticky. Změna analogového zdroje během záznamu zachová stav kondenzátorů a cívek v aktuálním čase. Logická síť má ideální 0/1/X/Z. Nejde o validovaný RF simulátor.</p>');
$('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('shieldio-sim-theme',theme);};document.documentElement.dataset.theme=localStorage.getItem('shieldio-sim-theme')||'dark';
const componentKeys={r:'resistor',c:'capacitor',l:'inductor',d:'diode',v:'vdc',a:'vac',i:'idc',g:'gnd',o:'opamp',s:'switch'};
function placeComponent(type){if(!allowed(type,mode))return;setTool('select');placing=type;placementRotation=0;liveOriginal=null;renderLibrary();renderPreview();}
document.addEventListener('keydown',e=>{if($('#dialog').open||$('#diodeTable')?.open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable)return;const k=e.key.toLowerCase();if((e.metaKey||e.ctrlKey)&&k==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.metaKey||e.ctrlKey)&&k==='s'){e.preventDefault();saveProject();return;}if(e.metaKey||e.ctrlKey||e.altKey)return;if(k==='enter'&&selected?.kind==='component'){const c=project.components.find(c=>c.id===selected.id);if(c&&['input','switch'].includes(c.type)){e.preventDefault();toggleInput(c);return;}}if(k==='escape'){setTool('select');hideContext();return;}if(k==='r'&&e.shiftKey){e.preventDefault();rotateSelected();return;}if(k==='shift'&&wireStart){wireVerticalFirst=!wireVerticalFirst;renderPreview();return;}if(mode==='analog'&&componentKeys[k]){e.preventDefault();placeComponent(componentKeys[k]);return;}if(k==='escape'||k==='q')setTool('select');if(k==='w')setTool('wire');if(k==='m'&&selected?.kind==='component'){openInspector();$('#measureTarget')?.focus();}if(k==='delete'||k==='backspace'){e.preventDefault();deleteSelected();}if(e.code==='Space'){e.preventDefault();run();}});

new ResizeObserver(()=>{applyCamera();renderScopes();}).observe($('#drawing'));
let labUI=createDiodeLabUI({getProject:()=>project,getRecord:()=>record,getIndex:()=>sampleIndex(),onSourceChange:async value=>{const c=project.components.find(c=>c.id==='V1');if(!c)return;await parameterChange(c,'value',value);if(record){cursor=liveTime=record.time.at(-1);render();}},onMethodChange:async method=>{const c=project.components.find(c=>c.id==='V1');if(!c)return;stop();cursor=liveTime;const state=currentState();snapshot();project.demo.method=method;if(method==='meters'){project.demo.acParams=copy(c.params);c.type='vdc';c.params={value:0};}else{c.type='vac';c.params=copy(project.demo.acParams||{value:2,frequency:25,waveform:'triangle',offset:0,phase:0});}saveLocal();await compute({resume:false,preserve:!!state,state});if(record)cursor=liveTime=record.time.at(-1);toggleScopes(method==='meters');render();},onExportCSV:({csv,filename:name})=>download(name,csv,'text/csv;charset=utf-8'),onTableChange:()=>saveLocal()});
async function previewDiode(){await compute({resume:false});if(record){cursor=liveTime=record.time.at(-1);render();}}
function setSpeed(value){try{speed=validateSpeed(value);$('#speed').value=Math.log10(speed);$('#speedExact').value=speed;$('#speedValue').textContent=formatSpeed(speed);const f=dominantFrequency(project);$('#speedPeriod').textContent=f?Number((1/f/speed).toPrecision(3))+' s skutečného času / periodu':'';updateReadouts();}catch(e){toast(e.message,true);}}
$('#speedExact').onchange=e=>setSpeed(e.target.value);
$('#speedAdaptive').onclick=()=>{const f=dominantFrequency(project);setSpeed(adaptiveSpeed(project));if(f){project.settings.duration=2/f;scopes.forEach(s=>{s.span=2/f;s.follow=true;});$('#duration').value=project.settings.duration/8;saveLocal();renderScopes();if(record){cursor=liveTime;compute({resume:running,preserve:true,state:currentState()});}}};
$('#retrySolver').onclick=()=>compute({resume:false});
async function init(){try{const hash=location.hash.slice(1);let loaded=false;if(hash&&['j','z'].includes(hash[0])){if(hash.length>100000)throw Error('Příliš dlouhý odkaz.');let data=Uint8Array.from(atob(hash.slice(1).replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));if(hash[0]==='z')data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate'))).arrayBuffer());if(data.length>3000000)throw Error('Příliš velký projekt.');project=validateProject(JSON.parse(new TextDecoder().decode(data)));loaded=true;}if(!loaded){const ex=examples.find(e=>e.id===(exampleAliases[new URL(location.href).searchParams.get('example')]||new URL(location.href).searchParams.get('example')));if(ex){project=validateProject({...copy(ex.project),mode:ex.mode});loaded=true;}}if(!loaded){const saved=localStorage.getItem(storeKey);if(saved)try{project=validateProject(JSON.parse(saved));loaded=true;}catch{}if(!loaded)project=validateProject({...copy(examples.find(e=>e.id==='ohm').project),mode:'analog'});}mode=modeOf(project);try{const layout=JSON.parse(localStorage.getItem('shieldio-sim-layout'));if(layout)for(const [k,v]of [['--left',layout.left],['--right',layout.right],['--scope-height',layout.scope]])if(/^\s*\d+(?:\.\d+)?px\s*$/.test(v))document.documentElement.style.setProperty(k,v);}catch{}}catch(e){toast(e.message,true);project=blank();}configureMode();prepareDemo();previewLogic();render();requestAnimationFrame(fit);if(!examples.some(e=>e.id===(exampleAliases[new URL(location.href).searchParams.get('example')]||new URL(location.href).searchParams.get('example'))))chooseMode();if(project.demo?.kind==='diode-iv')await previewDiode();}
init();
